-- Seed: Vehicle Bill of Sale, Nigeria — the first live Template-tier document.
-- Content researched from Nigerian private vehicle sale practice (bill-of-sale
-- conventions used for MVAA/FRSC change-of-ownership, "as-is" sale norms).
-- Not a government-mandated form — Nigeria has none for private sales — but
-- reflects what buyers, sellers, and MVAA offices commonly expect on one.

insert into document_templates
  (document_type, country, title, intro, sections, signatures, fields, legal_note, seo_intro, status)
values (
  'vehicle-bill-of-sale',
  'ng',
  'VEHICLE BILL OF SALE',
  'This Vehicle Bill of Sale records the private sale and transfer of ownership of a motor vehicle between the parties named below, for use alongside the vehicle’s other papers when completing the formal change of ownership.',
  '[{"heading":"1. PARTIES","body":"This Vehicle Bill of Sale (\"Agreement\") is made on {{saleDate}} at {{saleLocation}} between:\n\nSELLER: {{sellerName}}, of {{sellerAddress}}, phone {{sellerPhone}}, ID: {{sellerIdType}} (\"Seller\"); and\n\nBUYER: {{buyerName}}, of {{buyerAddress}}, phone {{buyerPhone}}, ID: {{buyerIdType}} (\"Buyer\").\n\nThe Seller and Buyer are together referred to as the \"Parties.\""},{"heading":"2. VEHICLE DESCRIPTION","body":"The Seller sells, and the Buyer buys, the following motor vehicle (the \"Vehicle\"):\n\nYear: {{vehicleYear}}\nMake: {{vehicleMake}}\nModel: {{vehicleModel}}\nColour: {{vehicleColour}}\nPlate Number: {{plateNumber}}\nVIN/Chassis Number: {{vin}}\nEngine Number: {{engineNumber}}"},{"heading":"3. PURCHASE PRICE","body":"The total purchase price for the Vehicle is NGN {{salePrice}} (the \"Purchase Price\"). The Seller acknowledges receipt of the full Purchase Price from the Buyer in cleared funds as of the date of this Agreement. Ownership of the Vehicle passes to the Buyer upon execution of this Agreement and handover of the Vehicle, its keys, and its original documents."},{"heading":"4. CONDITION OF SALE","body":"The Vehicle is sold \"AS IS\" and \"AS INSPECTED.\" The Buyer confirms that they have inspected the Vehicle to their satisfaction prior to signing this Agreement. The Seller makes no warranty or guarantee as to the condition, quality, or fitness of the Vehicle beyond what is expressly stated in this Agreement, and shall not be liable for any defect discovered after the date of this Agreement, except where the Seller has knowingly concealed a material defect."},{"heading":"5. SELLER''S WARRANTIES","body":"The Seller warrants that: (a) the Seller is the true and lawful owner of the Vehicle; (b) the Vehicle is free of any lien, encumbrance, or claim by a third party; (c) there are no outstanding fines, levies, or penalties tied to the Vehicle or its plate number as at the date of this Agreement; and (d) the Seller has full right and authority to sell the Vehicle."},{"heading":"6. TRANSFER OF OWNERSHIP","body":"The Parties agree to cooperate in good faith to complete the formal change of ownership of the Vehicle at the relevant State Motor Vehicle Administration Agency (MVAA) or equivalent office, including providing this Agreement, valid identification, and any other document reasonably required. The Buyer shall be responsible for the cost and process of the change of ownership and vehicle particulars update unless the Parties agree otherwise in writing."},{"heading":"7. RISK OF LOSS","body":"Risk of loss, theft, or damage to the Vehicle passes to the Buyer upon handover of the Vehicle, regardless of when formal ownership transfer at the MVAA is completed."},{"heading":"8. GOVERNING LAW","body":"This Agreement shall be governed by and construed in accordance with the laws of the Federal Republic of Nigeria."},{"heading":"9. ENTIRE AGREEMENT","body":"This Agreement constitutes the entire understanding between the Parties concerning the sale of the Vehicle and supersedes all prior discussions, representations, or agreements, whether oral or written."},{"heading":"10. SEVERABILITY","body":"If any provision of this Agreement is found to be invalid or unenforceable, the remaining provisions shall continue in full force and effect."},{"heading":"11. COUNTERPARTS","body":"This Agreement may be signed in counterparts, including by the Parties signing separate but identical copies, each of which shall be deemed an original."}]'::jsonb,
  '[{"role":"Seller"},{"role":"Witness to Seller"},{"role":"Buyer"},{"role":"Witness to Buyer"}]'::jsonb,
  '[{"id":"saleDate","label":"Date of Sale","type":"date","placeholder":"","required":true},{"id":"saleLocation","label":"Place of Signing (City/State)","type":"text","placeholder":"e.g. Lagos, Nigeria","required":true},{"id":"sellerName","label":"Seller''s Full Name","type":"text","placeholder":"","required":true},{"id":"sellerAddress","label":"Seller''s Address","type":"text","placeholder":"","required":true},{"id":"sellerPhone","label":"Seller''s Phone Number","type":"text","placeholder":"","required":true},{"id":"sellerIdType","label":"Seller''s ID Type & Number","type":"text","placeholder":"e.g. NIN 12345678901","required":true},{"id":"buyerName","label":"Buyer''s Full Name","type":"text","placeholder":"","required":true},{"id":"buyerAddress","label":"Buyer''s Address","type":"text","placeholder":"","required":true},{"id":"buyerPhone","label":"Buyer''s Phone Number","type":"text","placeholder":"","required":true},{"id":"buyerIdType","label":"Buyer''s ID Type & Number","type":"text","placeholder":"e.g. NIN 10987654321","required":true},{"id":"vehicleYear","label":"Vehicle Year","type":"text","placeholder":"e.g. 2015","required":true},{"id":"vehicleMake","label":"Vehicle Make","type":"text","placeholder":"e.g. Toyota","required":true},{"id":"vehicleModel","label":"Vehicle Model","type":"text","placeholder":"e.g. Corolla","required":true},{"id":"vehicleColour","label":"Vehicle Colour","type":"text","placeholder":"","required":true},{"id":"plateNumber","label":"Plate Number","type":"text","placeholder":"","required":false},{"id":"vin","label":"VIN / Chassis Number","type":"text","placeholder":"","required":true},{"id":"engineNumber","label":"Engine Number","type":"text","placeholder":"","required":false},{"id":"salePrice","label":"Sale Price (₦)","type":"text","placeholder":"e.g. 4,500,000","required":true}]'::jsonb,
  'Nigeria has no single government-mandated bill-of-sale form for private vehicle sales — this document reflects the fields Nigerian buyers, sellers, and State Motor Vehicle Administration Agency (MVAA) offices commonly expect: full names, phone numbers, valid ID, VIN, plate number, price, and signatures from both parties plus a witness each. Keep this signed document together with the vehicle’s other papers — it is usually required to complete the formal change of ownership.',
  'A Vehicle Bill of Sale is the private written record that a car has changed hands in Nigeria — who sold it, who bought it, which vehicle, for how much, and when. It is not a government-issued form, but it is the document Nigerian buyers and sellers rely on as proof of the transaction, and it is typically required alongside valid ID and the vehicle’s existing papers when completing the formal change of ownership at a State Motor Vehicle Administration Agency (MVAA) or FRSC office. Fill in the details below to generate a properly formatted Bill of Sale you can sign, print, and keep with your other vehicle documents.',
  'published'
)
on conflict (document_type, country) do update set
  title = excluded.title,
  intro = excluded.intro,
  sections = excluded.sections,
  signatures = excluded.signatures,
  fields = excluded.fields,
  legal_note = excluded.legal_note,
  seo_intro = excluded.seo_intro,
  status = excluded.status;
